#!/usr/bin/env python3
"""A small persistent HTTP key-value service."""

from __future__ import annotations

import argparse
import json
import math
import os
import signal
import sys
import tempfile
import threading
import time
from dataclasses import dataclass
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from pathlib import Path
from typing import Any
from urllib.parse import unquote_to_bytes, urlsplit


MAX_BODY_BYTES = 1024 * 1024


class StoreError(Exception):
    """Raised when durable storage cannot be read or written."""


@dataclass
class Entry:
    value: Any
    expires_at: float | None


class Store:
    def __init__(self, path: Path):
        self.path = path
        self._lock = threading.RLock()
        self._entries: dict[str, Entry] = {}
        self._load()

    def _load(self) -> None:
        if not self.path.exists():
            return
        try:
            with self.path.open("r", encoding="utf-8") as handle:
                document = json.load(handle)
            raw_entries = document["entries"]
            if not isinstance(raw_entries, dict):
                raise ValueError("entries must be an object")
            now = time.time()
            discarded_expired = False
            loaded: dict[str, Entry] = {}
            for key, raw in raw_entries.items():
                if not isinstance(key, str) or not isinstance(raw, dict):
                    raise ValueError("invalid entry")
                if set(raw) != {"value", "expires_at"}:
                    raise ValueError("invalid entry shape")
                expires_at = raw["expires_at"]
                if expires_at is not None:
                    if (
                        isinstance(expires_at, bool)
                        or not isinstance(expires_at, (int, float))
                        or not math.isfinite(expires_at)
                    ):
                        raise ValueError("invalid expiration")
                    expires_at = float(expires_at)
                    if expires_at <= now:
                        discarded_expired = True
                        continue
                loaded[key] = Entry(raw["value"], expires_at)
            self._entries = loaded
            if discarded_expired:
                self._persist_locked()
        except (OSError, ValueError, KeyError, TypeError, json.JSONDecodeError) as exc:
            raise StoreError(f"cannot load data file {self.path}: {exc}") from exc

    def _prune_locked(self) -> bool:
        now = time.time()
        expired = [
            key
            for key, entry in self._entries.items()
            if entry.expires_at is not None and entry.expires_at <= now
        ]
        for key in expired:
            del self._entries[key]
        return bool(expired)

    def _document_locked(self) -> dict[str, Any]:
        return {
            "entries": {
                key: {"value": entry.value, "expires_at": entry.expires_at}
                for key, entry in self._entries.items()
            }
        }

    def _persist_locked(self) -> None:
        parent = self.path.parent
        parent.mkdir(parents=True, exist_ok=True)
        temporary_name: str | None = None
        try:
            fd, temporary_name = tempfile.mkstemp(
                prefix=f".{self.path.name}.", suffix=".tmp", dir=parent
            )
            with os.fdopen(fd, "w", encoding="utf-8") as handle:
                json.dump(
                    self._document_locked(),
                    handle,
                    ensure_ascii=False,
                    separators=(",", ":"),
                    allow_nan=False,
                )
                handle.write("\n")
                handle.flush()
                os.fsync(handle.fileno())
            os.replace(temporary_name, self.path)
            temporary_name = None
            try:
                directory_fd = os.open(parent, os.O_RDONLY)
                try:
                    os.fsync(directory_fd)
                finally:
                    os.close(directory_fd)
            except OSError:
                # Directory fsync is unavailable on some platforms. The atomic
                # replacement itself has already completed successfully.
                pass
        except (OSError, TypeError, ValueError) as exc:
            raise StoreError(f"cannot persist data file {self.path}: {exc}") from exc
        finally:
            if temporary_name is not None:
                try:
                    os.unlink(temporary_name)
                except FileNotFoundError:
                    pass

    def get(self, key: str) -> tuple[bool, Any]:
        with self._lock:
            if self._prune_locked():
                self._persist_locked()
            entry = self._entries.get(key)
            return (False, None) if entry is None else (True, entry.value)

    def keys(self) -> list[str]:
        with self._lock:
            if self._prune_locked():
                self._persist_locked()
            return sorted(self._entries)

    def put(self, key: str, value: Any, ttl_seconds: float | None) -> bool:
        with self._lock:
            self._prune_locked()
            created = key not in self._entries
            previous = self._entries.get(key)
            expires_at = None if ttl_seconds is None else time.time() + ttl_seconds
            self._entries[key] = Entry(value, expires_at)
            try:
                self._persist_locked()
            except StoreError:
                if previous is None:
                    del self._entries[key]
                else:
                    self._entries[key] = previous
                raise
            return created

    def delete(self, key: str) -> bool:
        with self._lock:
            pruned = self._prune_locked()
            previous = self._entries.pop(key, None)
            if previous is None:
                if pruned:
                    self._persist_locked()
                return False
            try:
                self._persist_locked()
            except StoreError:
                self._entries[key] = previous
                raise
            return True

    def flush(self) -> None:
        with self._lock:
            self._prune_locked()
            self._persist_locked()


class KVHTTPServer(ThreadingHTTPServer):
    daemon_threads = False
    allow_reuse_address = True

    def __init__(self, address: tuple[str, int], store: Store):
        super().__init__(address, RequestHandler)
        self.store = store


class RequestHandler(BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"
    server_version = "persistent-kv/1"

    @property
    def kv_server(self) -> KVHTTPServer:
        return self.server  # type: ignore[return-value]

    def log_message(self, format_string: str, *args: Any) -> None:
        print(
            f"{self.address_string()} - {format_string % args}",
            file=sys.stderr,
            flush=True,
        )

    def _send_json(self, status: int, payload: Any | None = None) -> None:
        body = b"" if payload is None else json.dumps(
            payload, ensure_ascii=False, separators=(",", ":"), allow_nan=False
        ).encode("utf-8")
        self.send_response(status)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        if body:
            self.wfile.write(body)

    def _error(self, status: int, message: str) -> None:
        self._send_json(status, {"error": message})

    def _read_json(self) -> Any:
        transfer_encoding = self.headers.get("Transfer-Encoding")
        if transfer_encoding:
            raise HTTPInputError(400, "transfer encoding is not supported")
        length_text = self.headers.get("Content-Length")
        if length_text is None:
            raise HTTPInputError(411, "Content-Length is required")
        try:
            length = int(length_text)
        except ValueError as exc:
            raise HTTPInputError(400, "invalid Content-Length") from exc
        if length < 0:
            raise HTTPInputError(400, "invalid Content-Length")
        if length > MAX_BODY_BYTES:
            self.close_connection = True
            raise HTTPInputError(413, "request body exceeds 1 MiB")
        raw = self.rfile.read(length)
        if len(raw) != length:
            raise HTTPInputError(400, "incomplete request body")
        try:
            return json.loads(raw.decode("utf-8"))
        except (UnicodeDecodeError, json.JSONDecodeError) as exc:
            raise HTTPInputError(400, "malformed JSON") from exc

    @staticmethod
    def _decode_key(path: str) -> str | None:
        prefix = "/v1/kv/"
        if not path.startswith(prefix):
            return None
        encoded = path[len(prefix) :]
        hex_digits = frozenset("0123456789abcdefABCDEF")
        position = 0
        while position < len(encoded):
            if encoded[position] == "%":
                if (
                    position + 2 >= len(encoded)
                    or encoded[position + 1] not in hex_digits
                    or encoded[position + 2] not in hex_digits
                ):
                    raise HTTPInputError(400, "invalid URL encoding in key")
                position += 3
            else:
                position += 1
        try:
            key = unquote_to_bytes(encoded).decode("utf-8")
        except UnicodeDecodeError as exc:
            raise HTTPInputError(400, "key must be valid UTF-8") from exc
        if not key or "/" in key:
            raise HTTPInputError(400, "key must be non-empty and cannot contain '/'")
        return key

    def _path(self) -> str:
        return urlsplit(self.path).path

    def do_GET(self) -> None:
        try:
            path = self._path()
            if path == "/health":
                self._send_json(200, {"status": "ok"})
                return
            if path == "/v1/keys":
                self._send_json(200, {"keys": self.kv_server.store.keys()})
                return
            key = self._decode_key(path)
            if key is not None:
                found, value = self.kv_server.store.get(key)
                if found:
                    self._send_json(200, {"key": key, "value": value})
                else:
                    self._error(404, "key not found")
                return
            self._error(404, "route not found")
        except HTTPInputError as exc:
            self._error(exc.status, exc.message)
        except StoreError as exc:
            self.log_error("storage error: %s", exc)
            self._error(500, "storage error")

    def do_PUT(self) -> None:
        try:
            key = self._decode_key(self._path())
            if key is None:
                self._error(404, "route not found")
                return
            document = self._read_json()
            if not isinstance(document, dict):
                raise HTTPInputError(400, "request body must be a JSON object")
            if "value" not in document or not set(document).issubset(
                {"value", "ttl_seconds"}
            ):
                raise HTTPInputError(
                    400, "body must contain value and optional ttl_seconds"
                )
            ttl = document.get("ttl_seconds")
            if ttl is not None:
                if (
                    isinstance(ttl, bool)
                    or not isinstance(ttl, (int, float))
                    or not math.isfinite(ttl)
                    or ttl <= 0
                ):
                    raise HTTPInputError(400, "ttl_seconds must be finite and > 0")
                ttl = float(ttl)
            created = self.kv_server.store.put(key, document["value"], ttl)
            self._send_json(201 if created else 200, {"key": key, "value": document["value"]})
        except HTTPInputError as exc:
            self._error(exc.status, exc.message)
        except StoreError as exc:
            self.log_error("storage error: %s", exc)
            self._error(500, "storage error")

    def do_DELETE(self) -> None:
        try:
            key = self._decode_key(self._path())
            if key is None:
                self._error(404, "route not found")
                return
            if self.kv_server.store.delete(key):
                self._send_json(204)
            else:
                self._error(404, "key not found")
        except HTTPInputError as exc:
            self._error(exc.status, exc.message)
        except StoreError as exc:
            self.log_error("storage error: %s", exc)
            self._error(500, "storage error")

    def _unsupported(self) -> None:
        path = self._path()
        try:
            known = path in {"/health", "/v1/keys"} or self._decode_key(path) is not None
        except HTTPInputError as exc:
            self._error(exc.status, exc.message)
            return
        if known:
            self._error(405, "method not allowed")
        else:
            self._error(404, "route not found")

    do_POST = _unsupported
    do_PATCH = _unsupported
    do_OPTIONS = _unsupported
    do_HEAD = _unsupported


class HTTPInputError(Exception):
    def __init__(self, status: int, message: str):
        super().__init__(message)
        self.status = status
        self.message = message


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--host", default="127.0.0.1")
    parser.add_argument("--port", type=int, required=True)
    parser.add_argument("--data", type=Path, required=True)
    args = parser.parse_args()
    if not 0 <= args.port <= 65535:
        parser.error("--port must be between 0 and 65535")
    return args


def main() -> int:
    args = parse_args()
    try:
        store = Store(args.data)
        server = KVHTTPServer((args.host, args.port), store)
    except (OSError, StoreError) as exc:
        print(f"startup error: {exc}", file=sys.stderr, flush=True)
        return 1

    stopping = threading.Event()

    def stop(signum: int, _frame: Any) -> None:
        if stopping.is_set():
            return
        stopping.set()
        print(f"received signal {signum}, shutting down", file=sys.stderr, flush=True)
        threading.Thread(target=server.shutdown, daemon=True).start()

    signal.signal(signal.SIGTERM, stop)
    signal.signal(signal.SIGINT, stop)
    print(f"LISTENING {server.server_address[1]}", flush=True)
    try:
        server.serve_forever(poll_interval=0.1)
    finally:
        server.server_close()
        try:
            store.flush()
        except StoreError as exc:
            print(f"shutdown storage error: {exc}", file=sys.stderr, flush=True)
            return 1
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
#!/usr/bin/env python3
"""Dependency-free integration tests for server.py."""

import http.client
import json
import os
import signal
import subprocess
import sys
import tempfile
import time
import unittest
from pathlib import Path
from urllib.parse import quote


ROOT = Path(__file__).resolve().parent


class RunningServer:
    def __init__(self, data_file: Path):
        self.process = subprocess.Popen(
            [
                sys.executable,
                str(ROOT / "server.py"),
                "--host",
                "127.0.0.1",
                "--port",
                "0",
                "--data",
                str(data_file),
            ],
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True,
        )
        assert self.process.stdout is not None
        line = self.process.stdout.readline().strip()
        if not line.startswith("LISTENING "):
            stderr = self.process.stderr.read() if self.process.stderr else ""
            raise RuntimeError(f"server did not start: {line!r} {stderr}")
        self.port = int(line.split()[1])

    def request(self, method: str, path: str, body=None, headers=None):
        connection = http.client.HTTPConnection("127.0.0.1", self.port, timeout=3)
        request_headers = dict(headers or {})
        encoded = body
        if body is not None and not isinstance(body, (bytes, str)):
            encoded = json.dumps(body, separators=(",", ":"))
            request_headers.setdefault("Content-Type", "application/json")
        connection.request(method, path, body=encoded, headers=request_headers)
        response = connection.getresponse()
        raw = response.read()
        result = (response.status, dict(response.getheaders()), raw)
        connection.close()
        return result

    def stop(self):
        if self.process.poll() is None:
            self.process.send_signal(signal.SIGTERM)
            self.process.wait(timeout=5)
        if self.process.stdout:
            self.process.stdout.close()
        if self.process.stderr:
            self.process.stderr.close()


class ServerTests(unittest.TestCase):
    def setUp(self):
        self.temporary = tempfile.TemporaryDirectory()
        self.data_file = Path(self.temporary.name) / "nested" / "data.json"
        self.server = RunningServer(self.data_file)

    def tearDown(self):
        self.server.stop()
        self.temporary.cleanup()

    @staticmethod
    def decoded(response):
        status, headers, raw = response
        body = None if not raw else json.loads(raw)
        return status, headers, body

    def test_crud_sorting_validation_and_limit(self):
        key = "hello world"
        path = "/v1/kv/" + quote(key, safe="")
        status, headers, body = self.decoded(
            self.server.request("PUT", path, {"value": {"answer": 42}})
        )
        self.assertEqual(201, status)
        self.assertEqual("application/json", headers["Content-Type"])
        self.assertEqual({"key": key, "value": {"answer": 42}}, body)

        status, _, _ = self.decoded(
            self.server.request("PUT", path, {"value": [1, None, True]})
        )
        self.assertEqual(200, status)
        self.assertEqual(
            (200, {"key": key, "value": [1, None, True]}),
            (lambda r: (r[0], r[2]))(self.decoded(self.server.request("GET", path))),
        )
        self.server.request("PUT", "/v1/kv/z", {"value": 1})
        self.server.request("PUT", "/v1/kv/a", {"value": 1})
        self.assertEqual(
            {"keys": ["a", "hello world", "z"]},
            self.decoded(self.server.request("GET", "/v1/keys"))[2],
        )

        invalid_cases = [
            ("PUT", "/v1/kv/", {"value": 1}),
            ("PUT", "/v1/kv/a%2Fb", {"value": 1}),
            ("PUT", "/v1/kv/x", []),
            ("PUT", "/v1/kv/x", {"ttl_seconds": 1}),
            ("PUT", "/v1/kv/x", {"value": 1, "ttl_seconds": 0}),
            ("PUT", "/v1/kv/x", {"value": 1, "ttl_seconds": True}),
        ]
        for method, invalid_path, invalid_body in invalid_cases:
            with self.subTest(path=invalid_path, body=invalid_body):
                status, _, body = self.decoded(
                    self.server.request(method, invalid_path, invalid_body)
                )
                self.assertEqual(400, status)
                self.assertIn("error", body)

        self.assertEqual(
            400,
            self.server.request(
                "PUT", "/v1/kv/x", b"{bad", {"Content-Type": "application/json"}
            )[0],
        )
        self.assertEqual(
            413,
            self.server.request("PUT", "/v1/kv/x", b"x" * (1024 * 1024 + 1))[0],
        )
        self.assertEqual(405, self.server.request("POST", "/health", b"")[0])
        self.assertEqual(404, self.server.request("GET", "/missing")[0])

        status, headers, raw = self.server.request("DELETE", path)
        self.assertEqual(204, status)
        self.assertEqual(b"", raw)
        self.assertEqual("application/json", headers["Content-Type"])
        self.assertEqual(404, self.server.request("DELETE", path)[0])

    def test_ttl_persistence_restart_and_health(self):
        self.assertEqual(
            {"status": "ok"},
            self.decoded(self.server.request("GET", "/health"))[2],
        )
        self.assertEqual(
            201,
            self.server.request("PUT", "/v1/kv/durable", {"value": "yes"})[0],
        )
        self.assertEqual(
            201,
            self.server.request(
                "PUT", "/v1/kv/short", {"value": "gone", "ttl_seconds": 0.15}
            )[0],
        )
        self.server.stop()
        time.sleep(0.25)
        self.server = RunningServer(self.data_file)
        self.assertEqual(200, self.server.request("GET", "/v1/kv/durable")[0])
        self.assertEqual(404, self.server.request("GET", "/v1/kv/short")[0])
        self.assertEqual(
            {"keys": ["durable"]},
            self.decoded(self.server.request("GET", "/v1/keys"))[2],
        )
        persisted = json.loads(self.data_file.read_text(encoding="utf-8"))
        self.assertNotIn("short", persisted["entries"])


if __name__ == "__main__":
    unittest.main(verbosity=2)
# Persistent HTTP key-value service

A dependency-free Python 3.11+ JSON HTTP service with TTLs and atomic,
thread-safe persistence.

## Run

```sh
python3 server.py --host 127.0.0.1 --port 8080 --data ./data.json
```

Passing `--port 0` selects a free port; the first stdout line reports it as
`LISTENING <port>`. Diagnostics are written to stderr. Send `SIGTERM` or press
Ctrl-C for a clean shutdown.

## API

```sh
curl -i -X PUT http://127.0.0.1:8080/v1/kv/example \
  -H 'Content-Type: application/json' \
  -d '{"value":{"message":"hello"},"ttl_seconds":60}'
curl http://127.0.0.1:8080/v1/kv/example
curl http://127.0.0.1:8080/v1/keys
curl -i -X DELETE http://127.0.0.1:8080/v1/kv/example
curl http://127.0.0.1:8080/health
```

Keys are URL-encoded UTF-8 strings. They may contain spaces but cannot be empty
or contain `/`. PUT bodies require `value` (any JSON value) and may contain a
finite, positive `ttl_seconds`. Request bodies are limited to 1 MiB.

The data file is replaced atomically after every mutation. Expired records are
removed during startup and normal access, so they do not return after restart.

## Tests

```sh
python3 -m unittest -v
```

The integration tests launch the server on a free port and cover CRUD,
validation, body limits, TTL expiry, persistence, restart, and clean shutdown.
