ROOT = Path(__file__).resolve().parent


class RunningServer:
    def __init__(self, data_file: Path):
        self.process = subprocess.Popen(
            [
                sys.executable,
                str(ROOT / "server.py"),
                "--host",
                "127.0.0.1",
                "--port",
