                if pruned:
                    self._persist_locked()
                return False
            try:
                self._persist_locked()
            except StoreError:
                self._entries[key] = previous
                raise
            return True

    def flush(self) -> None:
        with self._lock:
            self._prune_locked()
            self._persist_locked()


